function BookCoverLeverPressMaker.init() BookCoverLeverPressMaker.ironStock=18; BookCoverLeverPressMaker.bronzeStock=14; BookCoverLeverPressMaker.woodStock=10; BookCoverLeverPressMaker.leatherStock=8; BookCoverLeverPressMaker.silverStock=8; BookCoverLeverPressMaker.goldStock=6; BookCoverLeverPressMaker.jewelStock=4; BookCoverLeverPressMaker.pearlStock=4; BookCoverLeverPressMaker.productStock={}; BookCoverLeverPressMaker.buildings={}; BookCoverLeverPressMaker.maker=nil; BookCoverLeverPressMaker.activeMaking={}; BookCoverLeverPressMaker.totalProducts=0; BookCoverLeverPressMaker.dayTimer=0; print("[BookCoverLeverPressMaker] Royal Book Cover Lever Press Maker System initialized (6 products, 4 buildings)") end
function BookCoverLeverPressMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BookCoverLeverPressMaker.maker={name=n or ("Vzvodnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzvodnik najet: %s (spretnost: %d)",BookCoverLeverPressMaker.maker.name,s),"success") end; return true end
function BookCoverLeverPressMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BookCoverLeverPressMaker.build(id) local ok,e=BookCoverLeverPressMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BookCoverLeverPressMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BookCoverLeverPressMaker.getQualityBonus() local b=0; for _,bd in ipairs(BookCoverLeverPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BookCoverLeverPressMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BookCoverLeverPressMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BookCoverLeverPressMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BookCoverLeverPressMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BookCoverLeverPressMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BookCoverLeverPressMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BookCoverLeverPressMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BookCoverLeverPressMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BookCoverLeverPressMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BookCoverLeverPressMaker.buildings==0 then return false,"Potrebna vzvodna delavnica" end; if not BookCoverLeverPressMaker.maker then return false,"Potreben vzvodnik" end; return true end
function BookCoverLeverPressMaker.make(pt,qty) qty=qty or 1; local ok,e=BookCoverLeverPressMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BookCoverLeverPressMaker.ironStock=BookCoverLeverPressMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BookCoverLeverPressMaker.bronzeStock=BookCoverLeverPressMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BookCoverLeverPressMaker.woodStock=BookCoverLeverPressMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BookCoverLeverPressMaker.leatherStock=BookCoverLeverPressMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BookCoverLeverPressMaker.silverStock=BookCoverLeverPressMaker.silverStock-d.silverCost*qty end; if d.goldCost then BookCoverLeverPressMaker.goldStock=BookCoverLeverPressMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BookCoverLeverPressMaker.jewelStock=BookCoverLeverPressMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BookCoverLeverPressMaker.pearlStock=BookCoverLeverPressMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BookCoverLeverPressMaker.maker then t=math.max(1,t-math.floor(BookCoverLeverPressMaker.maker.skill/13)) end; table.insert(BookCoverLeverPressMaker.activeMaking,{id="bookcoverleverpress_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BookCoverLeverPressMaker.completeMaking(m) local q=1.0+(BookCoverLeverPressMaker.getQualityBonus()/100); if BookCoverLeverPressMaker.maker then q=q+(BookCoverLeverPressMaker.maker.skill/140) end; q=math.min(2.5,q); BookCoverLeverPressMaker.productStock[m.productType]=(BookCoverLeverPressMaker.productStock[m.productType] or 0)+m.quantity; BookCoverLeverPressMaker.totalProducts=BookCoverLeverPressMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BookCoverLeverPressMaker.maker then BookCoverLeverPressMaker.maker.itemsMade=BookCoverLeverPressMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BookCoverLeverPressMaker.maker.skill=math.min(100,BookCoverLeverPressMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vzvod izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bookcoverleverpress.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BookCoverLeverPressMaker.update(dt) if not _G.state then return end; BookCoverLeverPressMaker.dayTimer=BookCoverLeverPressMaker.dayTimer+dt; if BookCoverLeverPressMaker.dayTimer>=30 then BookCoverLeverPressMaker.dayTimer=0; for i=#BookCoverLeverPressMaker.activeMaking,1,-1 do local m=BookCoverLeverPressMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BookCoverLeverPressMaker.completeMaking(m); table.remove(BookCoverLeverPressMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BookCoverLeverPressMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BookCoverLeverPressMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BookCoverLeverPressMaker.getStats() return {ironStock=BookCoverLeverPressMaker.ironStock,bronzeStock=BookCoverLeverPressMaker.bronzeStock,woodStock=BookCoverLeverPressMaker.woodStock,leatherStock=BookCoverLeverPressMaker.leatherStock,silverStock=BookCoverLeverPressMaker.silverStock,goldStock=BookCoverLeverPressMaker.goldStock,jewelStock=BookCoverLeverPressMaker.jewelStock,pearlStock=BookCoverLeverPressMaker.pearlStock,productStock=BookCoverLeverPressMaker.productStock,numBuildings=#BookCoverLeverPressMaker.buildings,hasMaker=BookCoverLeverPressMaker.maker~=nil,makerName=BookCoverLeverPressMaker.maker and BookCoverLeverPressMaker.maker.name or "—",makerSkill=BookCoverLeverPressMaker.maker and BookCoverLeverPressMaker.maker.skill or 0,activeMaking=#BookCoverLeverPressMaker.activeMaking,totalProducts=BookCoverLeverPressMaker.totalProducts} end
